import clsx from 'clsx';
import React, { forwardRef } from 'react';

import { blockquoteCSS } from './Blockquote.sty.js';
import type { DataTestId } from '../core/types/data-props.js';
import type { StylingProps } from '../core/types/styling-props.js';
import type { WithChildren } from '../core/types/with-children.js';

export interface BlockquoteProps
  extends WithChildren,
    StylingProps,
    DataTestId {
  /**
   * A URL that designates a source document or message for the information quoted.
   * This attribute is intended to point to information explaining the context for the quoted content.
   */
  cite?: string;
}

/**
 * The `Blockquote` component wraps longer text blocks and indicates that the passage is quoted from another source.
 */
export const Blockquote = /* @__PURE__ */ forwardRef<
  HTMLQuoteElement,
  BlockquoteProps
>((props, ref) => {
  const {
    children,
    cite,
    'data-testid': dataTestId,
    className: consumerClassName,
    style: consumerStyle,
    ...remainingProps
  } = props;

  return (
    <blockquote
      cite={cite}
      ref={ref}
      data-testid={dataTestId}
      className={clsx(blockquoteCSS, consumerClassName)}
      style={consumerStyle}
      {...remainingProps}
    >
      {children}
    </blockquote>
  );
});

(Blockquote as typeof Blockquote & { displayName: string }).displayName =
  'Blockquote';
